from pathlib import Path
p=Path(__file__).parent/'assets';p.mkdir(exist_ok=True)
def svg(name,body,w=240,h=240):
 (p/(name+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>')
def rect(x,y,w,h,r,fill,extra=''):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" {extra}/>'
